212	        claim.setNote(noteOf(note));
213	        claim.setLockedBy(null);
214	        claim.setEditedBy(user);
215	        Claim edited = claims.saveAndFlush(claim);
216	        Person person = people.findByIdAndSheetId(edited.getPersonId(), sheetId).orElseThrow();
217	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_EDITED", user, person, edited, edited.getNumber()));
218	        rollup.recordChanges(sheetId, user, before);
219	        return edited;
