636	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_RESETTLED", user, person, changed, changed.getNumber())
637	                + " old=" + old + " new=" + dueText(changed));
638	        watches.notifyWatchers(sheetId, user, person, changed.getNumber());
639	        rollup.recordChanges(sheetId, user, before);
640	        return changed;
641	    }
642	
643	    /** A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its date,
644	     *  takes the next number in the sequence it is numbered in (the sheet's, or its period's; a DRAFT, having no
645	     *  number, gets none) with its old number never used again, loses any figure a statement bound it to (it is live again until its new person's next statement), and is
646	     *  listed as its new person's newest claim. Refused for a role the permission matrix does not allow (by default a clerk), for a SETTLED or VOID claim, for a move to the
647	     *  person it is already of, for one due by inside a closed period or after the new person retired, and for a
648	     *  correction the new person has no SETTLED claim of that number for. */
649	    @Transactional
650	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
651	        return reassign(sheetId, user, id, toPersonId, false);
652	    }
653	
654	    /** Move a claim as {@link #reassign(String, String, long, long)} does, except that a bulk move also takes a
655	     *  claim already of the person it is moved to (it is listed again as that person's newest). */
656	    @Transactional
657	    public Claim reassign(String sheetId, String user, long id, long toPersonId, boolean bulk) {
658	        sheets.load(sheetId, user);
659	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
660	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
661	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
662	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
663	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
664	        if (!sheet.allows("reassign", roles.roleOf(sheetId, user))) {
665	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
666	        }
667	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
668	            throw new ResponseStatusException(HttpStatus.CONFLICT,
669	                    "A " + claim.getStatus() + " claim cannot be reassigned");
670	        }
671	        if (!bulk && claim.getPersonId().equals(to.getId())) {
672	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already " + to.getName() + "'s");
673	        }
674	        refuseIfClosed(sheetId, claim.getDueBy());
675	        refuseIfRetired(to, claim.getDate());
676	        refuseUnlessCorrects(sheetId, to.getId(), claim.getAmount(), claim.getCorrects());
677	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
678	        Rollup.Figures before = rollup.of(sheetId);
679	        claim.unbind();
680	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getNumber() != null) {
681	            claim.setNumber(nextNumber(sheet, claim.getDueBy()));
682	        }
683	        claim.reassign(to.getId(), claims.lastListed(sheetId) + 1);
684	        Claim moved = claims.saveAndFlush(claim);
685	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REASSIGNED", user, to, moved, moved.getNumber())
686	                + " from=" + from.getName() + " to=" + to.getName());
687	        rollup.recordChanges(sheetId, user, before);
688	        return moved;
689	    }
690	
691	    /** A claim split in two: the original, keeping the rest of its amount, and the new claim split off it. */
692	    public record Split(Claim original, Claim split) {
693	    }
694	
695	    /** Split an amount (more than 0.00 and less than its amount) off an OPEN claim: it keeps the rest and loses any
696	     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
697	     *  and note, the next number, opened by this user, a due-by fixed now from the terms in force on the date and
698	     *  naming the original as the claim it was split from, is listed as the person's newest; it is a late entry when
699	     *  the original is, and is numbered within the period of its own due-by. Refused for a claim
700	     *  that is not OPEN or is deferred, one with lines, one due by inside a closed period, an amount out of range, and a role the
701	     *  permission matrix does not allow to open a claim. */
702	    @Transactional
703	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
704	        sheets.load(sheetId, user);
705	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
706	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
707	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
708	        refuseIfClosed(sheetId, claim.getDueBy());
709	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
710	            throw new ResponseStatusException(HttpStatus.CONFLICT,
711	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one not deferred can");
712	        }
713	        if (!sheet.allows("open", roles.roleOf(sheetId, user))) {
714	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
715	        }
716	        if (!claim.getLines().isEmpty()) {
717	            throw new ResponseStatusException(HttpStatus.CONFLICT,
718	                    "A claim with lines has the amount of its lines; it cannot be split");
719	        }
720	        BigDecimal part = scaled(amount);
721	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
722	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
723	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
724	        }
725	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
726	        Rollup.Figures before = rollup.of(sheetId);
727	        claim.setAmount(claim.getAmount().subtract(part));
728	        claim.unbind();
729	        Claim original = claims.saveAndFlush(claim);
730	        LocalDate date = original.getDate();
731	        int terms = termsOf(sheet, person, date);
732	        LocalDate dueBy = holidays.dueBy(sheetId, date, terms);
733	        Claim added = new Claim(sheetId, person.getId(), part, date, dueBy, original.getNote(), null,
734	                claims.lastListed(sheetId) + 1);
735	        added.setTerms(terms);
736	        added.openAsSplit(nextNumber(sheet, dueBy), user, original.getNumber());
737	        added.setTags(original.getTags());
738	        if (original.isLateEntry()) {
739	            added.markLateEntry();
740	        }
741	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
742	        added = claims.saveAndFlush(added);
743	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
744	                + " into=" + added.getNumber());
745	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
746	        rollup.recordChanges(sheetId, user, before);
747	        return new Split(original, added);
748	    }
749	
750	    /** The PENDING claim a steward approves or rejects; refused for a clerk, a claim in any other status and one
751	     *  due by inside a closed period. */
752	    private Claim pendingClaim(String sheetId, String user, long id) {
753	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
754	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
755	        refuseIfClosed(sheetId, claim.getDueBy());
756	        if (claim.getStatus() != ClaimStatus.PENDING) {
757	            throw new ResponseStatusException(HttpStatus.CONFLICT,
758	                    "A " + claim.getStatus() + " claim is not waiting for approval");
759	        }
760	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
761	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim");
762	        }
763	        return claim;
764	    }
765	
766	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
767	     *  gained on top, raised to the floor in force on its date; null when it has no figure. */
768	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
769	        BigDecimal live = liveNow(sheet, claim, person);
770	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained,
771	        // raised to the floor.
772	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
773	        return figure == null ? null : floored(claim, figure.add(lateCharge(claim, figure, sheet, person.gradeOn(claim.getDate()))), sheet);
774	    }
775	
776	    /** A claim's live figure as rates and grades are now, bound by no statement; null when its grade has
777	     *  no rate in force on its date. */
778	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
779	        String sheetId = sheet.getId();
780	        return rates.of(sheetId).inForceOn(person.gradeOn(claim.getDate()), claim.getDate())
781	                .map(Rate::getRate)
782	                .map(rate -> liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
783	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
784	                .orElse(null);
785	    }
786	
787	    /** The due a claim shows as it is now: the due fixed when it was settled, else the one it would be settled at. */
788	    private BigDecimal shownDue(Sheet sheet, Claim claim, Person person) {
789	        return claim.getSettledDue() != null ? claim.getSettledDue() : dueNow(sheet, claim, person);
790	    }
791	
792	    private static String dueText(Claim claim) {
793	        return claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
794	    }
795	
796	    /** The next number on a sheet, locked by the caller, for a claim due by this day arriving there now, as
797	     *  {@link #nextNumber(Sheet, LocalDate)} gives it. */
798	    public String nextNumberOn(Sheet sheet, LocalDate dueBy) {
799	        return nextNumber(sheet, dueBy);
800	    }
801	
802	    /** The next number for a claim due by this day, opened now: within its period (<period name>-<n>, or X-<n>
803	     *  in no period) while the sheet's period numbering is on by its today, else the next number in the sheet-wide
804	     *  sequence its tree shares within the fiscal year of the day (FY<year>-<n>, counting from 1 each year). */
805	    private String nextNumber(Sheet sheet, LocalDate date) {
806	        if (!sheet.numbersPerPeriod()) {
807	            int year = sheet.fiscalYearOf(date);
808	            int last = lastNumberInTree(sheet, year);
809	            ClaimFiscalSequence sequence = fiscalSequences.findBySheetIdAndFiscalYear(sheet.getId(), year)
810	                    .orElseGet(() -> new ClaimFiscalSequence(sheet.getId(), year));
811	            String number = sequence.nextAfter(last);
812	            fiscalSequences.save(sequence);
813	            return number;
814	        }
815	        String prefix = prefixOn(sheet, date);
816	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
817	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
818	        String number = sequence.next();
819	        sequences.save(sequence);
820	        return number;
821	    }
822	
823	    /** The last sheet-wide number given in a fiscal year anywhere in the sheet's tree but the sheet itself: the
824	     *  sheet at the top of its line of parents and all of that sheet's descendants. The top sheet is locked so the
825	     *  tree's numbers are given one at a time. */
826	    private int lastNumberInTree(Sheet sheet, int fiscalYear) {
827	        List<String> ancestors = sheetStore.ancestorsOf(sheet.getId(), Integer.MAX_VALUE);
828	        String top = ancestors.isEmpty() ? sheet.getId() : ancestors.get(ancestors.size() - 1);
829	        if (!top.equals(sheet.getId())) {
830	            sheetStore.findLockedById(top);
831	        }
832	        Set<String> others = new HashSet<>(sheetStore.descendantsOf(top));
833	        others.add(top);
834	        others.remove(sheet.getId());
835	        return others.isEmpty() ? 0 : fiscalSequences.lastNumberOf(others, fiscalYear);
836	    }
837	
838	    /** The prefix of the numbers given within the period a day is in: its name, or X in no period. */
839	    private String prefixOn(Sheet sheet, LocalDate date) {
840	        return periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
841	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
842	    }
843	
844	    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
845	     *  date for its person's grade then (a claim with no due, or with no threshold then, needs none). */
846	    private static void refuseUnproven(Sheet sheet, Claim claim, Person person, BigDecimal due) {
847	        BigDecimal threshold = sheet.proofThresholdFor(person.gradeOn(claim.getDate()), claim.getDate());
848	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
849	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
850	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
851	        }
852	    }
853	
854	    /** Refuse to open a claim with an empty note whose due is above the note threshold in force on its date (a claim
855	     *  with no due, or on a sheet with no threshold then, needs none). */
856	    private static void refuseUnnoted(Sheet sheet, Claim claim, BigDecimal due) {
857	        BigDecimal threshold = sheet.noteThresholdOn(claim.getDate());
858	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
859	                && due.compareTo(threshold) > 0) {
860	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
861	                    "A claim whose due is above the note threshold of " + threshold + " needs a note first");
862	        }
863	    }
864	
865	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
866	     *  clerk limit (a claim with no due is within any limit). */
867	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
868	        BigDecimal limit = sheet.getClerkLimit();
869	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
870	            return false;
871	        }
872	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
873	    }
874	
875	    /** Refuse to void a SETTLED claim for anyone but a steward, and on a sheet's today more than
876	     *  {@value #SETTLED_VOID_DAYS} days after (or before) the day its log records it settled. */
877	    private void refuseSettledVoid(Sheet sheet, String user, Claim claim) {
878	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
879	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
880	        }
881	        LocalDate settled = claim.settledOn();
882	        LocalDate today = sheet.getToday();
883	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
884	            throw new ResponseStatusException(HttpStatus.CONFLICT,
885	                    "A SETTLED claim can be voided only within " + SETTLED_VOID_DAYS + " days of its settlement");
886	        }
887	    }
888	
889	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
890	     *  and a claim that is not a correction but names one. */
891	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
892	        if (amount.signum() >= 0) {
893	            if (corrects != null) {
894	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
895	                        "Only a correction (a negative amount) names a claim it corrects");
896	            }
897	            return;
898	        }
899	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
900	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
901	        if (!settled) {
902	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
903	                    "A correction must name the number of a SETTLED claim of the same person");
904	        }
905	    }
906	
907	    /** Refuse a change to a claim whose due-by is inside a closed period of the sheet. */
908	    private void refuseIfClosed(String sheetId, LocalDate date) {
909	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
910	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's due-by is inside a closed period");
911	        }
912	    }
913	
914	    /** Refuse opening a claim whose due-by is inside a period with a cap its person already has that many OPEN or
915	     *  PENDING claims in. */
916	    private void refuseOverCap(String sheetId, Claim claim) {
917	        for (Period period : periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId,
918	                claim.getDueBy(), claim.getDueBy())) {
919	            if (period.getClaimCap() == null) {
920	                continue;
921	            }
922	            long held = claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId()).stream()
923	                    .filter(c -> !c.getId().equals(claim.getId()))
924	                    .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
925	                    .filter(c -> period.contains(c.getDueBy()))
926	                    .count();
927	            if (held >= period.getClaimCap()) {
928	                throw new ResponseStatusException(HttpStatus.CONFLICT, "This person already has " + held
929	                        + " open claims in period " + period.getName() + ", its cap");
930	            }
931	        }
932	    }
933	
934	    /** Refuse a claim dated after its person's retirement date. */
935	    private static void refuseIfRetired(Person person, LocalDate date) {
936	        if (person.refusesClaimOn(date)) {
937	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
938	                    "That claim is dated after " + person.getName() + " retired");
939	        }
940	    }
941	
942	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
943	    private static String entry(String event, String user, Person person, Claim claim, String number) {
944	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
945	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
946	                + (number == null ? "" : " number=" + number);
947	    }
948	
949	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
950	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
951	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
952	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
953	    }
954	
955	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
956	     *  claim of the same person it corrects. */
957	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
958	        if (claim.getCorrects() == null) {
959	            return claim.getDate();
960	        }
961	        return sheetClaims.stream()
962	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
963	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
964	    }
965	
966	    /** The day a claim's overdue days are counted from: its due-by plus the grace days, in force on its date, of
967	     *  {@code grade} (its person's grade in force on its date). Its due-by itself is unchanged. */
968	    public static LocalDate overdueFrom(Claim claim, Sheet sheet, String grade) {
969	        return claim.getDueBy().plusDays(sheet.graceFor(grade, claim.getDate()));
970	    }
971	
972	    /** Whether a claim whose person is of {@code grade} on its date is overdue on the sheet's today: OPEN or PENDING,
973	     *  and its due-by plus its grade's grace days is before today. */
974	    public static boolean isOverdue(Claim claim, Sheet sheet, String grade) {
975	        return claim.getStatus().isOpen() && overdueFrom(claim, sheet, grade).isBefore(sheet.getToday());
976	    }
977	
978	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
979	     *  full 30 days past its due-by plus its grade's grace days ({@code grade}: its person's grade in force on its
980	     *  date), the late percent in force on that boundary date (that day plus 30, 60, 90 ... days) of the figure
981	     *  plus the charges of the boundaries before it (compounding), rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, or it is a correction. */
982	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
983	        BigDecimal none = BigDecimal.ZERO.setScale(2);
984	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
985	            return none;
986	        }
987	        return lateChargeAsOpen(claim, figure, sheet, grade);
988	    }
989	
990	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
991	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet, String grade) {
992	        BigDecimal none = BigDecimal.ZERO.setScale(2);
993	        if (figure == null || claim.isCorrection()) {
994	            return none;
995	        }
996	        LocalDate from = overdueFrom(claim, sheet, grade);
997	        long periods = ChronoUnit.DAYS.between(from, sheet.getToday()) / 30;
998	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
999	        BigDecimal charge = none;
1000	        for (long k = 1; k <= periods; k++) {
1001	            charge = charge.add(dueOn(figure.add(charge), sheet.latePctOn(from.plusDays(30 * k)), rounding));
1002	        }
1003	        return charge;
1004	    }
1005	
1006	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds. The floor is not applied
1007	     *  to it: it is applied last, to the figure with its late charge (see {@link #floored(Claim, BigDecimal, Sheet)}). */
1008	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, RoundingMode rounding) {
1009	        return dueOn(claim.getAmount(), rate, rounding);
1010	    }
1011	
1012	    /** A claim's due (its figure with its late charge) raised to the floor in force on its date, unless it is a
1013	     *  correction. */
1014	    public static BigDecimal floored(Claim claim, BigDecimal due, Sheet sheet) {
1015	        return due == null || claim.isCorrection() || sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
1016	    }
1017	
1018	    /** A live due raised to the sheet's floor when it is below it. */
1019	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
1020	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
1021	    }
1022	
1023	    /** The terms in days a claim of the person dated {@code date} is due by: the person's own, else their grade's
1024	     *  in force then, else the sheet's then. */
1025	    private static int termsOf(Sheet sheet, Person person, LocalDate date) {
1026	        return person.getTerms() != null ? person.getTerms() : sheet.termsFor(person.gradeOn(date), date);
1027	    }
1028	
1029	    private static BigDecimal scaled(BigDecimal amount) {
1030	        return amount.setScale(2, RoundingMode.UNNECESSARY);
1031	    }
1032	
1033	    /** An external reference as kept: trimmed, none when blank. */
1034	    public static String refOf(String ref) {
1035	        return ref == null || ref.isBlank() ? null : ref.trim();
1036	    }
1037	
1038	    /** Tags as kept: each trimmed and lower-cased, blanks and repeats dropped, sorted and joined by commas; none
1039	     *  when there are none. */
1040	    public static String tagsOf(String tags) {
1041	        if (tags == null) {
1042	            return null;
1043	        }
1044	        String joined = String.join(",", new TreeSet<>(Arrays.stream(tags.split(","))
1045	                .map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty()).toList()));
1046	        return joined.isEmpty() ? null : joined;
1047	    }
1048	
1049	    /** The refusal of an external reference already used on the sheet. */
1050	    public static ResponseStatusException refUsed(String ref) {
1051	        return new ResponseStatusException(HttpStatus.CONFLICT, "The reference " + ref + " is already used on this sheet");
1052	    }
1053	
1054	    private static String noteOf(String note) {
1055	        return note == null ? "" : note.trim();
1056	    }
1057	}
