import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { HoldView, PersonView } from './people';

/** DRAFT when added, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID, as can a SETTLED
 *  one by a steward within 7 days of its settlement. A clerk settling a
 *  claim above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (OPEN again). */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

export interface ClaimView {
  id: number;
  personId: number;
  /** The amount with exactly two decimals, e.g. "10.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on its sheet, given when opened: sheet-wide ("1", "2", ...) or within its period
   *  ("P1-1", or "X-1" in no period) while the sheet numbers per period; null while a draft. */
  number: string | null;
  /** The due fixed when the claim was settled, with exactly two decimals; null while it is not
   *  settled, or if its grade had no rate then (its due then follows the rate as an open one does). */
  settledDue: string | null;
  /** The signed-in name of the user who opened the claim; null while a draft. */
  openedBy: string | null;
  /** Whether its person's last statement binds the claim, to `statedDue`. */
  stated: boolean;
  /** The figure the claim had at its person's last statement, while bound by it, with exactly two
   *  decimals; null when not bound, while PENDING (it then follows the rate), or if it had no figure then (it stays n/a). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
   *  any other claim. */
  corrects: string | null;
  /** The day the claim is due by (yyyy-mm-dd): fixed when it was added, from its date and the terms of its
   *  person's grade in force then. */
  dueBy: string;
  /** The day the claim was deferred until (yyyy-mm-dd); null if it was never deferred. */
  deferredUntil: string | null;
  /** The claim's status log, oldest first: a line for each status it has had, the DRAFT it was added as first. */
  log: ClaimLogLine[];
  /** How many proofs have been given for the claim. */
  proofs: number;
  /** The number of the claim this one was split off; null on any other claim. */
  splitFrom: string | null;
  /** The signed-in name of the user who has the claim's editor open, locking it for others; null when no one has. */
  lockedBy: string | null;
  /** Whether the claim was added while the period its due-by is in was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-mm-dd) a reminder was written for the claim; null if it was never reminded. */
  remindedOn: string | null;
  /** The claim's external reference, unique on its sheet without regard to case; null when it has none. */
  ref: string | null;
  /** The claim's tags, sorted; empty when it has none. */
  tags: string[];
  /** The reason from the sheet's list the claim was voided with; null when not void or voided without one. */
  voidReason: string | null;
  /** The claim's comments, oldest first. */
  comments: ClaimComment[];
  /** The signed-in name of the user who last edited the claim; null if no one has. Like its opener, they
   *  cannot settle or approve it. */
  editedBy: string | null;
  /** The number of the settle batch that settled the claim; null when it was not settled by one. */
  batch: number | null;
  /** The claim's lines, in the order added; while it has any, its amount is their totals added up. */
  lines: ClaimLine[];
}

/** A line of a claim: its label, its quantity (a whole number, at least 1) and its unit amount with exactly two
 *  decimals. */
export interface ClaimLine {
  label: string;
  qty: number;
  unit: string;
}

/** A comment on a claim: the signed-in name of who wrote it, the sheet's today (yyyy-mm-dd) then, and its text. */
export interface ClaimComment {
  by: string;
  on: string;
  text: string;
}

/** A line of a claim's status log: the status it took, the signed-in name of who moved it there, the sheet's
 *  today (yyyy-mm-dd) then, and the due it had at that moment with exactly two decimals (null when it had none). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(c: ClaimView): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is deferred on the sheet's today: OPEN and deferred until a later day. While deferred it
 *  counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Pick<ClaimView, 'deferredUntil' | 'status'>, today: string): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today < c.deferredUntil;
}

/** Whether an unstated OPEN or PENDING claim is left out of the live totals on the sheet's today: dated within one
 *  of these holds, or its person's retirement date (null: not retired) reached by today. */
function heldOn(c: ClaimView, holds: readonly HoldView[], today: string, retiredFrom: string | null): boolean {
  return (
    (retiredFrom !== null && today !== '' && retiredFrom <= today) ||
    holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to))
  );
}

/** Whether the claim counts in the live totals on the sheet's today for a person with these holds and retirement
 *  date: a deferred one does not, nor does an OPEN or PENDING one dated within a hold or of a person whose
 *  retirement date today has reached, unless a statement binds it. */
export function countsWithHolds(
  holds: readonly HoldView[],
  today: string,
  retiredFrom: string | null = null,
): (c: ClaimView) => boolean {
  return (c) =>
    counts(c) &&
    !isDeferred(c, today) &&
    (c.stated || (c.status !== 'OPEN' && c.status !== 'PENDING') || !heldOn(c, holds, today, retiredFrom));
}

/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it: the last line dated on
 *  or before it; null when the claim was added after it. */
export function statusAt(c: Pick<ClaimView, 'log'>, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) if (line.on <= day) status = line.status;
  return status;
}

/** Whether the claim counts in a period's figures for a person with these holds: by the status it had at the end
 *  of the period's last day (`end`), and left out when deferred, held or retired as the live totals on the sheet's
 *  today say. */
export function countsAtEndWithHolds(
  holds: readonly HoldView[],
  today: string,
  end: string,
  retiredFrom: string | null = null,
): (c: ClaimView) => boolean {
  return (c) => {
    const status = statusAt(c, end);
    return (
      (status === 'OPEN' || status === 'PENDING' || status === 'SETTLED') &&
      !isDeferred(c, today) &&
      (c.stated || (c.status !== 'OPEN' && c.status !== 'PENDING') || !heldOn(c, holds, today, retiredFrom))
    );
  };
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
  theirs: readonly Pick<ClaimView, 'date' | 'number'>[],
): string {
  if (c.corrects === null) return c.date;
  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
}

/** A date (yyyy-mm-dd) so many days later. */
export function addDays(date: string, days: number): string {
  return new Date(Date.parse(date) + days * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and its due-by plus the grace
 *  days of its person's grade (in force on its date) a day before it. */
export function isOverdue(c: Pick<ClaimView, 'dueBy' | 'status' | 'deferredUntil'>, today: string, graceDays = 0): boolean {
  return (c.status === 'OPEN' || c.status === 'PENDING') && !isDeferred(c, today) && addDays(c.dueBy, graceDays) < today;
}

/** A claim as the form submits it: a blank date takes the sheet's today. A negative amount is a correction,
 *  which names in `corrects` the number of the claim it corrects. */
export interface ClaimForm {
  amount: string;
  date: string | null;
  note: string;
  corrects: string | null;
  /** The external reference (trimmed by the store); null or blank for none. */
  ref: string | null;
  /** The tags, comma separated (each trimmed and lower-cased by the store, repeats dropped); blank for none. */
  tags: string;
}

/** What a quick-add made: the person the claim is for, whether they were added by it, and the claim. */
export interface QuickAddView {
  person: PersonView;
  personAdded: boolean;
  claim: ClaimView;
}

/** What a paste did: how many claims it added and the claims, in the order added. */
export interface PasteView {
  added: number;
  claims: ClaimView[];
}

/** What a split did: the claim split, keeping the rest of its amount, and the new claim split off it. */
export interface SplitView {
  original: ClaimView;
  split: ClaimView;
}

/** What a bulk open did: how many it opened and refused, and the claims it opened. */
export interface BulkOpenView {
  opened: number;
  refused: number;
  claims: ClaimView[];
}

/** What a bulk settle did: how many it settled (PENDING ones included) and refused, the claims it settled, and the
 *  settle batch they make. */
export interface BulkSettleView {
  settled: number;
  refused: number;
  claims: ClaimView[];
  /** The number of the settle batch it made; null when it settled none. */
  batch: number | null;
}

/** What a bulk move did: how many it moved and refused, and the claims it moved. */
export interface BulkReassignView {
  reassigned: number;
  refused: number;
  claims: ClaimView[];
}

/** What a bulk re-date did: how many it re-dated and refused, and the claims it re-dated. */
export interface BulkRedateView {
  redated: number;
  refused: number;
  claims: ClaimView[];
}

/** An amount the form accepts: 0.00 or more, with up to two decimals. */
export const AMOUNT_PATTERN = /^\d+(\.\d{1,2})?$/;

/** An amount the claim form accepts: AMOUNT_PATTERN, or a negative one (a correction). */
export const CLAIM_AMOUNT_PATTERN = /^-?\d+(\.\d{1,2})?$/;

/** An amount ("12.3", "4", "-0.5") in whole cents, so sums are exact. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const total = Number(whole) * 100 + Number(frac.padEnd(2, '0').slice(0, 2));
  return negative ? -total : total;
}

/** Whole cents as an amount with two decimals, e.g. "-0.30". */
export function money(total: number): string {
  const abs = Math.abs(total);
  return `${total < 0 ? '-' : ''}${Math.trunc(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

// The claims people on a sheet have made, listed newest first.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);

  list(sheetId: string): Observable<ClaimView[]> {
    return this.http.get<ClaimView[]>(`${this.base(sheetId)}/claims`);
  }

  add(sheetId: string, personId: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/people/${personId}/claims`, claim);
  }

  /** Add a DRAFT claim for the person named `name`, dated the sheet's today; one not on the sheet is
   *  added first with grade A. Refused as a whole when the person or the claim is. */
  quickAdd(sheetId: string, name: string, amount: string): Observable<QuickAddView> {
    return this.http.post<QuickAddView>(`${this.base(sheetId)}/quick-add`, { name, amount });
  }

  /** Add a DRAFT claim per line of name,amount,date,note, in order, for people already on the sheet; a note
   *  ending in " #<reference>" gives the claim that reference. Refused as a whole when any line is. */
  paste(sheetId: string, text: string): Observable<PasteView> {
    return this.http.post<PasteView>(`${this.base(sheetId)}/claims/paste`, { text });
  }

  update(sheetId: string, id: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}`, claim);
  }

  /** Open a draft's editor, locking it for other users until it is saved or cancelled or the sheet's today
   *  changes. Refused while another user has it open. */
  lock(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/lock`, null);
  }

  /** Cancel a claim's editor, releasing the lock it took. */
  unlock(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.delete<ClaimView>(`${this.base(sheetId)}/claims/${id}/lock`);
  }

  changeStatus(sheetId: string, id: number, status: ClaimStatus, reason?: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/status`, { status, reason: reason ?? null });
  }

  /** Defer an OPEN claim until `until` (yyyy-mm-dd), a day after the sheet's today. */
  defer(sheetId: string, id: number, until: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/defer`, { until });
  }

  /** A steward re-dates an OPEN or PENDING claim to `date` (yyyy-mm-dd). */
  redate(sheetId: string, id: number, date: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/date`, { date });
  }

  /** Raise a claim's proofs count by one; refused for a SETTLED or VOID claim. */
  addProof(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/proofs`, {});
  }

  /** Add a line to a DRAFT claim; refused for a claim that is not a DRAFT, in a closed period or locked by another
   *  user, and for a blank label, a quantity below 1 or a unit amount with more than two decimals. */
  addLine(sheetId: string, id: number, line: ClaimLine): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/lines`, line);
  }

  /** Comment on a claim as the signed-in user on the sheet's today; an empty comment is refused. */
  comment(sheetId: string, id: number, text: string): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/comments`, { text });
  }

  /** Write a reminder for an OPEN or PENDING claim, dated the sheet's today; refused once it was reminded today. */
  remind(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/claims/${id}/reminders`, {});
  }

  /** A steward approves a PENDING claim: it is SETTLED, its due fixed as it is now. */
  approve(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/approve`, {});
  }

  /** A steward re-settles a SETTLED claim: its due fixed again as it would be today as an open, unbound claim. */
  resettle(sheetId: string, id: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/resettle`, {});
  }

  /** A steward rejects a PENDING claim with a reason: it is OPEN again. */
  reject(sheetId: string, id: number, reason: string): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/reject`, { reason });
  }

  /** A steward moves a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, is no
   *  longer bound by a statement, and is listed as that person's newest claim. */
  reassign(sheetId: string, id: number, personId: number): Observable<ClaimView> {
    return this.http.put<ClaimView>(`${this.base(sheetId)}/claims/${id}/person`, { personId });
  }

  /** Split `amount` off an OPEN claim into a new OPEN claim of the same person, date and note. */
  split(sheetId: string, id: number, amount: string): Observable<SplitView> {
    return this.http.post<SplitView>(`${this.base(sheetId)}/claims/${id}/split`, { amount });
  }

  /** Open each of the claims that can be opened, numbered in list order; the rest are refused and left as they are. */
  bulkOpen(sheetId: string, ids: readonly number[]): Observable<BulkOpenView> {
    return this.http.post<BulkOpenView>(`${this.base(sheetId)}/claims/bulk-open`, { ids });
  }

  /** Settle each of the claims that can be settled, in list order, as a single settle would; the rest are refused
   *  and left as they are. */
  bulkSettle(sheetId: string, ids: readonly number[]): Observable<BulkSettleView> {
    return this.http.post<BulkSettleView>(`${this.base(sheetId)}/claims/bulk-settle`, { ids });
  }

  /** Move each of the claims to the person, in list order, as a single move would; the rest are refused and left
   *  as they are. */
  bulkReassign(sheetId: string, ids: readonly number[], personId: number): Observable<BulkReassignView> {
    return this.http.post<BulkReassignView>(`${this.base(sheetId)}/claims/bulk-reassign`, { ids, personId });
  }

  /** Re-date each of the claims to `date` (yyyy-mm-dd), in list order, as a single re-date would; the rest are
   *  refused and left as they are. */
  bulkRedate(sheetId: string, ids: readonly number[], date: string): Observable<BulkRedateView> {
    return this.http.post<BulkRedateView>(`${this.base(sheetId)}/claims/bulk-redate`, { ids, date });
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}

