protected readonly api = inject(People);
private readonly claimsApi = inject(Claims);
private readonly statementsApi = inject(Statements);
private readonly snapshotsApi = inject(Snapshots);
private readonly patronsApi = inject(Patrons);
private readonly plansApi = inject(Plans);
private readonly watchesApi = inject(Watches);
private readonly consolidatedApi = inject(Consolidated);
protected readonly rates = inject(Rates);
protected readonly periods = inject(Periods);
private readonly session = inject(Session);
/** The person on the sheet with the signed-in user's name, by name or alias as names are compared; null when none. */
protected readonly me = computed(() => {
  const user = this.session.user()?.trim().toLowerCase();
  if (!user) return null;
  return this.people().find((p) =>
    p.name.toLowerCase() === user || (p.aliases ?? []).some((a) => a.toLowerCase() === user)) ?? null;
});
private readonly pools = inject(Pools);

protected readonly grades = GRADES;
protected readonly money = money;
protected readonly people = signal<PersonView[]>([]);
/** The figures of the sheet's descendants, as each of them shows its own, re-read on each (re)load. */
private readonly descendants = signal<DescendantFigures>(NO_DESCENDANTS);
/** The people listed: retired people only while "show retired" is on. Totals still count everyone. */
protected readonly listed = computed(() =>
  this.api.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
);
protected readonly sortKeys = SORT_KEYS;
/** Each signed-in user's sort key for this screen; 'added' (list order) until they choose one. */
private readonly sortByUser = signal<ReadonlyMap<string, SortKey>>(new Map());
protected readonly sortKey = computed(() =>
  this.sortByUser().get(this.session.user()?.trim().toLowerCase() ?? '') ?? 'added');
/** The people listed, in the chosen order: only what the screen shows; positions and every action in list order
 *  still go by list order. A stable sort, so equal keys keep list order. */
protected readonly shown = computed(() => {
  const list = this.listed();
  const due = this.dueByPerson();
  switch (this.sortKey()) {
    case 'name':
      return [...list].sort((a, b) => {
        const x = a.name.trim().toLowerCase(), y = b.name.trim().toLowerCase();
        return x < y ? -1 : x > y ? 1 : 0;
      });
    case 'grade':
      return [...list].sort((a, b) => GRADES.indexOf(this.gradeToday(a)) - GRADES.indexOf(this.gradeToday(b)));
    case 'due-total': {
      const key = (p: PersonView) => due.get(p.id) ?? Number.POSITIVE_INFINITY;
      return [...list].sort((a, b) => {
        const x = key(a), y = key(b);
        return x === y ? 0 : x < y ? -1 : 1;
      });
    }
    default:
      return list;
  }
});
/** The person being retired, so a second press waits for the first. */
